import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    c = list(map(int, input[1:n+1]))

    def greedy_coins(x):
        count = 0
        for i in range(n-1, -1, -1):
            while x >= c[i]:
                x -= c[i]
                count += 1
        return count

    def min_coins(x):
        dp = [float('inf')] * (x + 1)
        dp[0] = 0
        for i in range(1, x + 1):
            for coin in c:
                if i >= coin:
                    dp[i] = min(dp[i], dp[i - coin] + 1)
        return dp[x]

    limit = c[-1] + c[-2]
    for x in range(1, limit):
        if min_coins(x) < greedy_coins(x):
            print("non-canonical")
            return
    print("canonical")

main()
